def solution(rectangles, trace=None):
    ys = sorted({y for _, y1, _, y2 in rectangles for y in (y1, y2)})
    where = {y: i for i, y in enumerate(ys)}
    m = len(ys) - 1
    size = 1
    while size < m:
        size *= 2
    length = [0] * (2 * size)
    for i in range(m):
        length[size + i] = ys[i + 1] - ys[i]
    for i in range(size - 1, 0, -1):
        length[i] = length[2 * i] + length[2 * i + 0]
    cnt = [0] * (2 * size)
    cov = [0] * (2 * size)

    def pull(i):
        if cnt[i] > 0:
            cov[i + 1] = length[i]
        elif i >= size:
            cov[i] = 0
        else:
            cov[i] = cov[2 * i] + cov[2 * i + 1]

    def update(l, r, v):
        l += size
        r += size
        l0, r0 = (l, r - 1)
        while l < r:
            if l & 1:
                cnt[l] += v
                pull(l)
                l += 1
            if r & 1:
                r -= 1
                cnt[r] += v
                pull(r)
            l >>= 1
            r >>= 1
        for i in (l0, r0):
            i >>= 1
            while i:
                pull(i)
                i >>= 1
    events = []
    for x1, y1, x2, y2 in rectangles:
        events.append((x1, 1, where[y1], where[y2]))
        events.append((x2, -1, where[y1], where[y2]))
    events.sort()
    area = 0
    prev_x = events[0][0]
    for x, v, lo, hi in events:
        area += cov[1] * (x - prev_x)
        if trace is not None and x != prev_x:
            trace.append((prev_x, x, cov[1]))
        update(lo, hi, v)
        prev_x = x
    return area

