def best_matching(w):
    """w[i][j] ≥ 0인 표에서, 행과 열을 겹치지 않게 짝지어 얻는 값의 합의 최댓값(헝가리안 방법)."""
    if not w or not w[0]:
        return 0
    if len(w) > len(w[0]):
        w = [list(col) for col in zip(*w)]
    n, m = (len(w), len(w[0]))
    INF = float('inf')
    u, v = ([0] * (n + 1), [0] * (m + 1))
    match = [0] * (m + 1)
    way = [0] * (m + 1)
    for i in range(1, n + 1):
        match[0] = i
        j0 = 0
        minv = [INF] * (m + 1)
        used = [False] * (m + 1)
        while True:
            used[j0] = True
            i0, delta, j1 = (match[j0], INF, 0)
            for j in range(1, m + 1):
                if not used[j]:
                    cur = -w[i0 - 1][j - 1] - u[i0] - v[j]
                    if cur < minv[j]:
                        minv[j], way[j] = (cur, j0)
                    if minv[j] < delta:
                        delta, j1 = (minv[j], j)
            for j in range(m + 1):
                if used[j]:
                    u[match[j]] += delta
                    v[j] -= delta
                else:
                    minv[j] -= delta
            j0 = j1
            if match[j0] == 0:
                break
        while j0:
            j1 = way[j0]
            match[j0] = match[j1]
            j0 = j1
    return sum((w[match[j] - 1][j - 1] for j in range(1, m + 1) if match[j]))

def children_lists(n, g):
    adj = [[] for _ in range(n + 1)]
    for p, q in g:
        adj[p].append(q)
        adj[q].append(p)
    kids = [[] for _ in range(n + 1)]
    order, seen, stack = ([], [False] * (n + 1), [1])
    seen[1] = True
    while stack:
        v = stack.pop()
        order.append(v)
        for c in adj[v]:
            if not seen[c]:
                seen[c] = True
                kids[v].append(c)
                stack.append(c)
    return (kids, order[::-1])

def solution(n1, g1, n2, g2, table=None):
    kids1, order1 = children_lists(n1, g1)
    kids2, order2 = children_lists(n2, g2)
    dp = [[0] * (n2 - 1) for _ in range(n1 + 1)]
    for u in order1:
        for v in order2:
            w = [[dp[c][d - 1] for d in kids2[v]] for c in kids1[u]]
            dp[u][v] = 1 + best_matching(w)
    if table is not None:
        table.extend(dp)
    return dp[1][1]

